#include "../src/world_clip.h"
#include <stdio.h>
int main(void){unsigned count;int cx,cy,focal;while(scanf("%u %d %d %d",&count,&cx,&cy,&focal)==4){TaxiWorldClippedPolygon p={.count=count};if(count!=3&&count!=4)return 2;for(unsigned i=0;i<count;i++){int x,y,z;if(scanf("%d %d %d",&x,&y,&z)!=3)return 3;p.vertices[i]=(TaxiWorldClipVertex){.x=x,.y=y,.z=z,.u=17+(int)i,.v=31+(int)i,.attribute=47+(int)i};}TaxiWorldClippedPolygon saved=p;TaxiTrafficProjection projection={.center_x=cx,.center_y=cy,.focal=focal};TaxiTrafficScreenBounds b;int rc=taxi_world_project_vertices(&p,&projection,&b);if(rc)return 4;for(unsigned i=0;i<count;i++){TaxiWorldClipVertex a=p.vertices[i],old=saved.vertices[i];if(a.x!=old.x||a.y!=old.y||a.z!=old.z||a.u!=old.u||a.v!=old.v||a.attribute!=old.attribute)return 5;}printf("%ld %ld %ld %ld ",(long)b.left,(long)b.top,(long)b.right,(long)b.bottom);for(unsigned i=0;i<count;i++)printf("%ld %ld ",(long)p.vertices[i].screen_x,(long)p.vertices[i].screen_y);puts("");}return 0;}
